def bsearch(L, t):
    lo, hi = 0, len(L) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if L[mid] == t:
            return mid
        elif L[mid] < t:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
print(bsearch([2, 5, 7, 11, 13, 17], 13))
